import { concatMap, forkJoin, map, of, type Observable } from "rxjs";

import { multisetDiff } from "../runtime/diff.ts";
import { selectRows } from "../runtime/rows.ts";
import type {
  IArrivalBatch,
  IArrivalRow,
  IGenProgram,
  IRow,
  IRowValue,
  ISqlSeam,
  ITickDeltas,
  SqlStatement,
} from "../runtime/types.ts";

interface IBootStatement {
  sql: string;
  params: readonly (string | number)[];
}

type IGenProgramWithBoot = IGenProgram & { readonly boot: readonly IBootStatement[] };

function bindArgs(values: readonly IRowValue[]): (string | number | bigint)[] {
  return values.map((value) => (typeof value === "number" && Number.isInteger(value) ? BigInt(value) : value));
}

const ddl: readonly string[] = [
  `CREATE TABLE "eprintln_hit" ("path" TEXT NOT NULL, "line_number" TEXT NOT NULL, PRIMARY KEY ("path", "line_number")) WITHOUT ROWID`,
  `CREATE TABLE "eprintln_waived" ("path" TEXT NOT NULL, "line_number" TEXT NOT NULL, PRIMARY KEY ("path", "line_number")) WITHOUT ROWID`,
  `CREATE TABLE "eprintln_waiver_line" ("path" TEXT NOT NULL, "waiver_line" TEXT NOT NULL, PRIMARY KEY ("path", "waiver_line")) WITHOUT ROWID`,
];

const relColumns: Record<string, readonly string[]> = {
  eprintln_hit: ["path", "line_number"],
  eprintln_waived: ["path", "line_number"],
  eprintln_waiver_line: ["path", "waiver_line"],
};

const arrivalTargets: readonly string[] = ["eprintln_hit", "eprintln_waiver_line"];

const boot: readonly IBootStatement[] = [
  { sql: `INSERT OR IGNORE INTO "eprintln_hit" ("path", "line_number") VALUES (?, ?)`, params: ["src/db.rs", 40] },
  { sql: `INSERT OR IGNORE INTO "eprintln_hit" ("path", "line_number") VALUES (?, ?)`, params: ["src/db.rs", 88] },
  { sql: `INSERT OR IGNORE INTO "eprintln_waiver_line" ("path", "waiver_line") VALUES (?, ?)`, params: ["src/db.rs", 39] },
];

type Snapshot = {
  readonly eprintln_hit: readonly IRow[];
  readonly eprintln_waived: readonly IRow[];
  readonly eprintln_waiver_line: readonly IRow[];
};

function readSnapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    eprintln_hit: selectRows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' THEN json_extract("path", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("path", '$.args')) || ')' ELSE "path" END AS "path", CASE WHEN json_valid("line_number") AND json_type("line_number") = 'object' THEN json_extract("line_number", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("line_number", '$.args')) || ')' ELSE "line_number" END AS "line_number" FROM "eprintln_hit"`, relColumns.eprintln_hit!),
    eprintln_waived: selectRows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' THEN json_extract("path", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("path", '$.args')) || ')' ELSE "path" END AS "path", CASE WHEN json_valid("line_number") AND json_type("line_number") = 'object' THEN json_extract("line_number", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("line_number", '$.args')) || ')' ELSE "line_number" END AS "line_number" FROM "eprintln_waived"`, relColumns.eprintln_waived!),
    eprintln_waiver_line: selectRows(seam, `SELECT CASE WHEN json_valid("path") AND json_type("path") = 'object' THEN json_extract("path", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("path", '$.args')) || ')' ELSE "path" END AS "path", CASE WHEN json_valid("waiver_line") AND json_type("waiver_line") = 'object' THEN json_extract("waiver_line", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("waiver_line", '$.args')) || ')' ELSE "waiver_line" END AS "waiver_line" FROM "eprintln_waiver_line"`, relColumns.eprintln_waiver_line!),
  });
}

const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; addSql: string; delSql: string | null }> = {
  eprintln_hit: { kind: "set", addSql: `INSERT OR IGNORE INTO "eprintln_hit" ("path", "line_number") VALUES (?, ?)`, delSql: `DELETE FROM "eprintln_hit" WHERE "path" = ? AND "line_number" = ?` },
  eprintln_waiver_line: { kind: "set", addSql: `INSERT OR IGNORE INTO "eprintln_waiver_line" ("path", "waiver_line") VALUES (?, ?)`, delSql: `DELETE FROM "eprintln_waiver_line" WHERE "path" = ? AND "waiver_line" = ?` },
};

function arrivalStatement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`range_join_over_arithmetic: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`range_join_over_arithmetic: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.delSql === null) {
      throw new Error(`range_join_over_arithmetic: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.delSql, args: bindArgs(arrival.row) };
  }
  return { sql: template.addSql, args: bindArgs(arrival.row) };
}

function applyArrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrivalStatement);
  return seam.runner.batch(seam.db, statements);
}

function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "eprintln_waived";\nINSERT OR IGNORE INTO "eprintln_waived" ("path", "line_number") SELECT b0."path", b1."line_number" FROM "eprintln_waiver_line" b0, "eprintln_hit" b1 WHERE b1."path" = b0."path"`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const eprintln_hit = multisetDiff(before.eprintln_hit, after.eprintln_hit);
  const eprintln_waived = multisetDiff(before.eprintln_waived, after.eprintln_waived);
  const eprintln_waiver_line = multisetDiff(before.eprintln_waiver_line, after.eprintln_waiver_line);
  return {
    rels: [
      { rel: "eprintln_hit", add: eprintln_hit.add, del: eprintln_hit.del },
      { rel: "eprintln_waived", add: eprintln_waived.add, del: eprintln_waived.del },
      { rel: "eprintln_waiver_line", add: eprintln_waiver_line.add, del: eprintln_waiver_line.del },
    ],
    carryPending: false,
  };
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // range_join_over_arithmetic: no edge rules -- absorb arrivals, recompute levels, diff.
}

export const program: IGenProgramWithBoot = {
  name: "range_join_over_arithmetic",
  ddl,
  relColumns,
  arrivalTargets,
  boot,
  tick: runTick,
};
